//! 📨️ Original History message fields keep their real native text and target index under nested receiving and cancellation receipts.
use super::{HistoryEdit,HistoryMessage,RetainedHistoryIdDecode,RetainedHistoryRecords,RetainedHistoryRecordsStep};
use ::protocol::{codec::RetainedWireFieldDecode,dictionary::RetainedSourceDictionary};
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress};
use std::mem::ManuallyDrop;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedHistoryMessageDecodeStep{Blocked,Progress,Ready,Closed}
pub struct RetainedHistoryMessagePartial{pub level:u8,pub code:Option<String>,pub message:Option<String>,pub target:Option<Vec<String>>,pub pending_target:Option<String>,pub op_index:Option<u32>}
pub struct RetainedHistoryMessageDecode{source_identity:(usize,usize),end:usize,position:usize,phase:u8,remaining:usize,partial:ManuallyDrop<Option<RetainedHistoryMessagePartial>>,id:ManuallyDrop<Option<RetainedHistoryIdDecode>>,field:ManuallyDrop<Option<RetainedWireFieldDecode>>,field_range:(usize,usize),targets:ManuallyDrop<Option<RetainedHistoryRecords<String>>>,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>,closing:bool,closed:bool}
impl RetainedHistoryMessageDecode{
 fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
 fn scalar(source:&[u8],position:&mut usize,end:usize)->Result<usize,ValueError>{let mut value=0u64;for index in 0..10{let byte=*source.get(*position).filter(|_|*position<end).ok_or_else(||Self::fault("original History message scalar is truncated"))?;*position+=1;if index==9&&byte>1{return Err(Self::fault("original History message scalar overflows"))}value|=u64::from(byte&127)<<(index*7);if byte&128==0{return usize::try_from(value).map_err(|_|Self::fault("original History message extent exceeds this platform"))}}Err(Self::fault("original History message scalar is not bounded"))}
 /// 🎟️ Admits the actual original borrowed record and empty partial field slots without native allocation.
 pub fn admit(source:&[u8],range:(usize,usize),grant:RetainedCloneGrant)->Result<Option<Self>,ValueError>{source.get(range.0..range.1).ok_or_else(||Self::fault("original History message escaped its source"))?;if grant.maximum_items==0||grant.maximum_depth==0{return Ok(None)}Ok(Some(Self{source_identity:(source.as_ptr()as usize,source.len()),end:range.1,position:range.0,phase:0,remaining:0,partial:ManuallyDrop::new(Some(RetainedHistoryMessagePartial{level:0,code:None,message:None,target:None,pending_target:None,op_index:None})),id:ManuallyDrop::new(None),field:ManuallyDrop::new(None),field_range:(0,0),targets:ManuallyDrop::new(None),receipt:Some((grant,RetainedCloneProgress{copied_items:1,..Default::default()})),closing:false,closed:false}))}
 fn validate_source(&self,source:&[u8])->Result<(),ValueError>{if self.source_identity!=(source.as_ptr()as usize,source.len()){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original History message source changed"))}Ok(())}
 fn covers(grant:RetainedCloneGrant,demand:RetirementDemand)->bool{grant.maximum_items>0&&grant.maximum_depth>=demand.depth&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes}
 fn nested(mut demand:RetirementDemand)->Result<RetirementDemand,ValueError>{demand.depth=demand.depth.checked_add(1).ok_or_else(||Self::fault("original History message depth overflow"))?;Ok(demand)}
 fn record(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{self.receipt=Some((grant,progress));if !progress.fits(grant){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original History message receipt exceeded its original grant").with_retained_progress(progress))}Ok(())}
 fn metadata(&mut self,grant:RetainedCloneGrant)->Result<RetainedHistoryMessageDecodeStep,ValueError>{self.record(grant,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistoryMessageDecodeStep::Progress)}
 pub fn receipt(&self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt}
 pub fn take_receipt(&mut self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt.take()}
 pub fn consumed_end(&self)->usize{self.position}
 pub fn is_ready(&self)->bool{!self.closing&&!self.closed&&self.phase==12&&self.receipt.is_none()}
 /// 📐️ Quotes all five physical axes and the actual child-plus-parent depth before changing either owner.
 pub fn demands(&self,source:&[u8],original_prior_edits:&[HistoryEdit],maximum_copy_bytes:usize)->Result<RetirementDemand,ValueError>{
  self.validate_source(source)?;if self.receipt.is_some()||self.closed{return Ok(Default::default())}
  if let Some(id)=self.id.as_ref(){return Self::nested(id.demands(source,original_prior_edits,maximum_copy_bytes)?)}
  if let Some(field)=self.field.as_ref(){return Self::nested(if self.closing{field.close_demands()}else{field.demands(&source[self.field_range.0..self.field_range.1],maximum_copy_bytes)?})}
  if self.closing{return Ok(RetirementDemand{depth:if self.targets.is_some(){2}else{1},..Default::default()})}
  if self.phase==9{return Self::nested(self.targets.as_ref().ok_or_else(||Self::fault("original History target index is absent"))?.demands()?)}
  Ok(RetirementDemand{depth:match self.phase{1=>3,3|6|10=>2,7=>2,_=>1},..Default::default()})
 }
 fn length_range(&self,source:&[u8])->Result<(usize,usize),ValueError>{let mut position=self.position;let length=Self::scalar(source,&mut position,self.end)?;let end=position.checked_add(length).filter(|end|*end<=self.end).ok_or_else(||Self::fault("original History message text is truncated"))?;Ok((position,end))}
 /// 🧵️ Advances one original scalar, granted field piece or typed target publication frontier.
 pub fn step(&mut self,source:&[u8],dictionary:&RetainedSourceDictionary,original_prior_edits:&[HistoryEdit],grant:RetainedCloneGrant)->Result<RetainedHistoryMessageDecodeStep,ValueError>{
  self.validate_source(source)?;if self.closing||self.closed||self.receipt.is_some(){return Ok(RetainedHistoryMessageDecodeStep::Blocked)}if self.is_ready(){return Ok(RetainedHistoryMessageDecodeStep::Ready)}let demand=self.demands(source,original_prior_edits,grant.maximum_copy_bytes)?;if !Self::covers(grant,demand){return Ok(RetainedHistoryMessageDecodeStep::Blocked)}
  if self.id.is_some(){if self.id.as_ref().unwrap().terminal_is_empty(){drop(self.id.take());self.phase=3;return self.metadata(grant)}let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let result=if self.id.as_ref().unwrap().is_ready(){self.id.as_mut().unwrap().take_ready_into(source,original_prior_edits,&mut self.partial.as_mut().unwrap().code,child_grant)}else{self.id.as_mut().unwrap().step(source,original_prior_edits,child_grant)};if let Some((_,progress))=self.id.as_mut().unwrap().take_receipt(){self.record(grant,progress)?}result?;return Ok(if self.receipt.is_some(){RetainedHistoryMessageDecodeStep::Progress}else{RetainedHistoryMessageDecodeStep::Blocked})}
  if self.field.is_some(){if self.field.as_ref().unwrap().terminal_is_empty(){drop(self.field.take());self.phase=if self.phase==4{5}else{9};return self.metadata(grant)}let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let result=if self.field.as_ref().unwrap().is_ready(){let partial=self.partial.as_mut().unwrap();let recipient=if self.phase==4{&mut partial.message}else{&mut partial.pending_target};self.field.as_mut().unwrap().take_text_into(recipient,child_grant)}else{self.field.as_mut().unwrap().advance(&source[self.field_range.0..self.field_range.1],child_grant)};if let Some((_,progress))=self.field.as_mut().unwrap().take_receipt(){self.record(grant,progress)?}result?;return Ok(if self.receipt.is_some(){RetainedHistoryMessageDecodeStep::Progress}else{RetainedHistoryMessageDecodeStep::Blocked})}
  match self.phase{
   0=>{let level=*source.get(self.position).filter(|_|self.position<self.end).ok_or_else(||Self::fault("original History message severity is absent"))?;if semio_framework_diagnostic::Severity::from_u8(level).is_none(){return Err(Self::fault("original History message severity is invalid"))}self.partial.as_mut().unwrap().level=level;self.position+=1;self.phase=1;},
   1=>{let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let mut id=RetainedHistoryIdDecode::admit(source,(self.position,self.end),dictionary,&[],child_grant)?.ok_or_else(||Self::fault("original History message code grant was not admitted"))?;self.position=id.consumed_end();let(_,progress)=id.take_receipt().unwrap();*self.id=Some(id);self.phase=2;self.record(grant,progress)?;return Ok(RetainedHistoryMessageDecodeStep::Progress)},
   3=>{let range=self.length_range(source)?;*self.field=Some(RetainedWireFieldDecode::new(&source[range.0..range.1],true));self.field_range=range;self.position=range.1;self.phase=4;},
   5=>{let mut position=self.position;let count=Self::scalar(source,&mut position,self.end)?;if count>self.end-position{return Err(Self::fault("original History message target count exceeds its record"))}self.remaining=count;self.position=position;self.phase=6;},
   6=>{let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let mut targets=RetainedHistoryRecords::admit(child_grant)?.ok_or_else(||Self::fault("original History target index grant was not admitted"))?;let(_,progress)=targets.take_receipt().unwrap();*self.targets=Some(targets);self.phase=7;self.record(grant,progress)?;return Ok(RetainedHistoryMessageDecodeStep::Progress)},
   7 if self.remaining!=0=>{let range=self.length_range(source)?;*self.field=Some(RetainedWireFieldDecode::new(&source[range.0..range.1],true));self.field_range=range;self.position=range.1;self.phase=8;},
   7=>{let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let result=self.targets.as_mut().unwrap().take_ready_into(&mut self.partial.as_mut().unwrap().target,child_grant);if let Some((_,progress))=self.targets.as_mut().unwrap().take_receipt(){self.record(grant,progress)?}result?;self.phase=10;return Ok(RetainedHistoryMessageDecodeStep::Progress)},
   9=>{let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let result=self.targets.as_mut().unwrap().append_original(&mut self.partial.as_mut().unwrap().pending_target,child_grant);if let Some((_,progress))=self.targets.as_mut().unwrap().take_receipt(){self.record(grant,progress)?}if result?==RetainedHistoryRecordsStep::Published{self.remaining-=1;self.phase=7}return Ok(if self.receipt.is_some(){RetainedHistoryMessageDecodeStep::Progress}else{RetainedHistoryMessageDecodeStep::Blocked})},
   10=>{if !self.targets.as_ref().unwrap().terminal_is_empty(){return Err(Self::fault("original History target index receipt is outstanding"))}drop(self.targets.take());self.phase=11;},
   11=>{let mut position=self.position;let tag=*source.get(position).filter(|_|position<self.end).ok_or_else(||Self::fault("original History message index presence is absent"))?;position+=1;let op_index=match tag{0=>None,1=>Some(u32::try_from(Self::scalar(source,&mut position,self.end)?).map_err(|_|Self::fault("original History message operation index exceeds u32"))?),_=>return Err(Self::fault("original History message index presence is invalid"))};self.partial.as_mut().unwrap().op_index=op_index;self.position=position;self.phase=12;},
   _=>return Err(Self::fault("original History message frontier is invalid")),
  }self.metadata(grant)
 }
 /// 📤️ Moves the exact complete original text/index owners into the actual typed message recipient.
 pub fn take_ready_into(&mut self,recipient:&mut Option<HistoryMessage>,grant:RetainedCloneGrant)->Result<RetainedHistoryMessageDecodeStep,ValueError>{if !self.is_ready()||recipient.is_some()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(RetainedHistoryMessageDecodeStep::Blocked)}let partial=self.partial.as_mut().unwrap();if partial.code.is_none()||partial.message.is_none()||partial.target.is_none()||partial.pending_target.is_some(){return Err(Self::fault("original History message ready fields are incomplete"))}let mut original=self.partial.take().unwrap();*recipient=Some(HistoryMessage{level:original.level,code:original.code.take().unwrap(),message:original.message.take().unwrap(),target:original.target.take().unwrap(),op_index:original.op_index});self.closed=true;self.record(grant,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistoryMessageDecodeStep::Closed)}
 pub fn partial_is_receivable(&self)->bool{self.closing&&!self.closed&&self.receipt.is_none()&&self.id.is_none()&&self.field.is_none()&&self.targets.is_none()&&self.partial.is_some()}
 /// 🧳️ Returns every actual partially received field before the parent can become empty.
 pub fn take_partial_into(&mut self,recipient:&mut Option<RetainedHistoryMessagePartial>,grant:RetainedCloneGrant)->Result<RetainedHistoryMessageDecodeStep,ValueError>{if !self.partial_is_receivable()||recipient.is_some()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(RetainedHistoryMessageDecodeStep::Blocked)}*recipient=self.partial.take();self.record(grant,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistoryMessageDecodeStep::Progress)}
 pub fn cancel(&mut self){self.closing=true;if let Some(id)=self.id.as_mut(){id.cancel()}if let Some(field)=self.field.as_mut(){field.cancel()}}
 /// ♻️ Pays child closure or partial target receiving before the separate parent metadata close.
 pub fn close_step(&mut self,source:&[u8],original_prior_edits:&[HistoryEdit],grant:RetainedCloneGrant)->Result<RetainedHistoryMessageDecodeStep,ValueError>{
  self.validate_source(source)?;if self.closed{return Ok(RetainedHistoryMessageDecodeStep::Closed)}if !self.closing||self.receipt.is_some(){return Ok(RetainedHistoryMessageDecodeStep::Blocked)}let demand=self.demands(source,original_prior_edits,grant.maximum_copy_bytes)?;if !Self::covers(grant,demand){return Ok(RetainedHistoryMessageDecodeStep::Blocked)}
  if self.id.is_some(){if self.id.as_ref().unwrap().terminal_is_empty(){drop(self.id.take());return self.metadata(grant)}let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let result=self.id.as_mut().unwrap().close_step(source,original_prior_edits,child_grant);if let Some((_,progress))=self.id.as_mut().unwrap().take_receipt(){self.record(grant,progress)?}result?;return Ok(if self.receipt.is_some(){RetainedHistoryMessageDecodeStep::Progress}else{RetainedHistoryMessageDecodeStep::Blocked})}
  if self.field.is_some(){if self.field.as_ref().unwrap().terminal_is_empty(){drop(self.field.take());return self.metadata(grant)}let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let result=self.field.as_mut().unwrap().close_step(child_grant);if let Some((_,progress))=self.field.as_mut().unwrap().take_receipt(){self.record(grant,progress)?}result?;return Ok(if self.receipt.is_some(){RetainedHistoryMessageDecodeStep::Progress}else{RetainedHistoryMessageDecodeStep::Blocked})}
  if self.targets.is_some(){if self.targets.as_ref().unwrap().terminal_is_empty(){drop(self.targets.take());return self.metadata(grant)}let child_grant=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};let result=self.targets.as_mut().unwrap().take_ready_into(&mut self.partial.as_mut().unwrap().target,child_grant);if let Some((_,progress))=self.targets.as_mut().unwrap().take_receipt(){self.record(grant,progress)?}result?;return Ok(if self.receipt.is_some(){RetainedHistoryMessageDecodeStep::Progress}else{RetainedHistoryMessageDecodeStep::Blocked})}
  if self.partial.is_some(){return Ok(RetainedHistoryMessageDecodeStep::Blocked)}self.closed=true;self.record(grant,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistoryMessageDecodeStep::Closed)
 }
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.receipt.is_none()&&self.partial.is_none()&&self.id.is_none()&&self.field.is_none()&&self.targets.is_none()}
}
impl Drop for RetainedHistoryMessageDecode{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original History message abandoned native receiving custody");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.partial);ManuallyDrop::drop(&mut self.id);ManuallyDrop::drop(&mut self.field);ManuallyDrop::drop(&mut self.targets)}}}}
